boundary_rows = [1, 5, 9, 13, 17, 21, 25]
boundary_cols = [0, 5, 10, 15, 20]

def section_type_from_corners(corners):
    non_7 = [v for v in corners if v != 7]
    if not non_7:
        return 3
    if len(set(non_7)) == 1:
        return non_7[0]
    counts = {}
    for v in non_7:
        counts[v] = counts.get(v, 0) + 1
    if counts.get(6, 0) > counts.get(4, 0):
        return 6
    return 4

c_left = [0, 5, 10, 15, 20]
c_right = [5, 10, 15, 20, 22]
r_top = boundary_rows
r_bottom = [5, 9, 13, 17, 21, 25, 26]

def get_section_type(r_band, c_band):
    if r_band > 6 or c_band > 4:
        raise ValueError(f"Invalid section band: ({r_band}, {c_band})")

    cap_left = c_left[c_band]
    cap_right = c_right[c_band]
    r_cap_top = r_top[r_band]

    corners = []
    corners.append(input_grid[r_cap_top][cap_left])  # TL
    corners.append(input_grid[r_cap_top][cap_right])  # TR

    if r_band < 6:
        r_cap_bottom = r_bottom[r_band]
        corners.append(input_grid[r_cap_bottom][cap_left])  # BL
        corners.append(input_grid[r_cap_bottom][cap_right])  # BR
    else:
        # Band 6: no bottom wall, no bottom corners
        pass

    return section_type_from_corners(corners)

