def get_section_band(r, c):
    if c in [0, 5, 10, 15, 20]:
        return None, None
    if r in [1, 5, 9, 13, 17, 21, 25]:
        return None, None

    if 0 < c < 5:
        c_band = 0
    elif 5 < c < 10:
        c_band = 1
    elif 10 < c < 15:
        c_band = 2
    elif 15 < c < 20:
        c_band = 3
    elif c == 21:
        c_band = 4
    else:
        return None, None

    if 1 < r < 5:
        r_band = 0
    elif 5 < r < 9:
        r_band = 1
    elif 9 < r < 13:
        r_band = 2
    elif 13 < r < 17:
        r_band = 3
    elif 17 < r < 21:
        r_band = 4
    elif 21 < r < 25:
        r_band = 5
    elif r > 25:
        r_band = 6
    else:
        return None, None

    return r_band, c_band

